function migrateCancelledToSubmitted() {
    if (localStorage.getItem(submittedMigrationKey)) return;
    const rows = list();;window.__pqExportCapture({"path":"modules/admin/js/workplace-history-store.js","scriptIndex":0,"offset":2988,"line":60,"name":"rows"},rows);
    let changed = false;;window.__pqExportCapture({"path":"modules/admin/js/workplace-history-store.js","scriptIndex":0,"offset":3014,"line":61,"name":"changed"},changed);
    rows.forEach(record => {
      if (record.status !== 'cancelled') return;
      record.status = 'submitted';
      changed = true;
    });
    // Apply this correction once; future user cancellations must stay cancelled.
    if (changed) localStorage.setItem(key, JSON.stringify(rows));
    localStorage.setItem(submittedMigrationKey, '1');
