function setStatus(id, status) {
    const rows = list();;window.__pqExportCapture({"path":"modules/admin/js/workplace-history-store.js","scriptIndex":0,"offset":3422,"line":72,"name":"rows"},rows);
    const record = rows.find(row => row.id === id);;window.__pqExportCapture({"path":"modules/admin/js/workplace-history-store.js","scriptIndex":0,"offset":3449,"line":73,"name":"record"},record);
    if (!record) throw new Error('Workplace history record not found.');
    const allowed = status === 'submitted' ? ['draft', 'resubmit']
      : status === 'cancelled' ? ['draft', 'submitted', 'approved', 'resubmit'] : [];;window.__pqExportCapture({"path":"modules/admin/js/workplace-history-store.js","scriptIndex":0,"offset":3575,"line":75,"name":"allowed"},allowed);
    if (!allowed.includes(record.status)) throw new Error('Unsupported Workplace history status transition.');
    record.status = status;
    if (status === 'submitted') {
      const now = new Date();;window.__pqExportCapture({"path":"modules/admin/js/workplace-history-store.js","scriptIndex":0,"offset":3899,"line":80,"name":"now"},now);
      const submitDate = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}`;;window.__pqExportCapture({"path":"modules/admin/js/workplace-history-store.js","scriptIndex":0,"offset":3936,"line":81,"name":"submitDate"},submitDate);
      let hasSubmitDate = false;;window.__pqExportCapture({"path":"modules/admin/js/workplace-history-store.js","scriptIndex":0,"offset":4075,"line":82,"name":"hasSubmitDate"},hasSubmitDate);
      record.fields = record.fields.map(([label, value]) => {
        if (!['submit date', 'submitted date'].includes(label.trim().toLowerCase())) return [label, value];
        hasSubmitDate = true;
        return [label, submitDate];
      });
      if (!hasSubmitDate) record.fields.push(['Submit Date', submitDate]);
    }
    localStorage.setItem(key, JSON.stringify(rows));
    return record;
  }

