function parseDate(value) {
    const text = String(value || '').trim();;window.__pqExportCapture({"path":"js/pending-approval-filter.js","scriptIndex":0,"offset":270,"line":6,"name":"text"},text);
    let match = text.match(/^(\d{4})-(\d{2})-(\d{2})(?:$|T)/);;window.__pqExportCapture({"path":"js/pending-approval-filter.js","scriptIndex":0,"offset":314,"line":7,"name":"match"},match);
    let year, month, day;
    if (match) {
      [, year, month, day] = match.map(Number);
    } else if ((match = text.match(/(?:^|\s)(\d{1,2})[/-](\d{1,2})[/-](\d{4})(?:$|\s)/))) {
      [, day, month, year] = match.map(Number);
    } else if ((match = text.match(/(?:^|\s)(\d{1,2})\s+([a-z]+)\s+(\d{4})(?:$|\s)/i))) {
      day = Number(match[1]);
      month = ['jan', 'feb', 'mar', 'apr', 'may', 'jun', 'jul', 'aug', 'sep', 'oct', 'nov', 'dec'].indexOf(match[2].slice(0, 3).toLowerCase()) + 1;
      year = Number(match[3]);
    } else return null;
    const date = new Date(year, month - 1, day);;window.__pqExportCapture({"path":"js/pending-approval-filter.js","scriptIndex":0,"offset":932,"line":18,"name":"date"},date);
    return month > 0 && date.getFullYear() === year && date.getMonth() === month - 1 && date.getDate() === day ? date : null;
  }

