    if (filters.startDate || filters.endDate) parts.push(`${filters.startDate || 'Any start date'} – ${filters.endDate || 'Any end date'}`);
    const names = { '1': '1 Day', '2-3': '2–3 Days', '4-5': '4–5 Days', gt5: '>5 Days' };;window.__pqExportCapture({"path":"js/pending-approval-filter.js","scriptIndex":0,"offset":3216,"line":64,"name":"names"},names);
