function setScope(scope, updateUrl = true) {
    activeScope = scope === 'team' ? 'team' : 'individual';
    const individualTab = document.getElementById('employeeCareerTabIndividual');;window.__pqExportCapture({"path":"modules/employee-career/js/employee-career-app.js","scriptIndex":0,"offset":1704,"line":27,"name":"individualTab"},individualTab);
    const teamTab = document.getElementById('employeeCareerTabTeam');;window.__pqExportCapture({"path":"modules/employee-career/js/employee-career-app.js","scriptIndex":0,"offset":1780,"line":28,"name":"teamTab"},teamTab);
    const individualActive = activeScope === 'individual';;window.__pqExportCapture({"path":"modules/employee-career/js/employee-career-app.js","scriptIndex":0,"offset":1859,"line":29,"name":"individualActive"},individualActive);
    individualTab?.classList.toggle('active', individualActive);
    teamTab?.classList.toggle('active', !individualActive);
    individualTab?.setAttribute('aria-selected', String(individualActive));
    teamTab?.setAttribute('aria-selected', String(!individualActive));
    if (individualTab) individualTab.tabIndex = individualActive ? 0 : -1;
    if (teamTab) teamTab.tabIndex = individualActive ? -1 : 0;
    if (updateUrl) {
      const url = new URL(location.href);;window.__pqExportCapture({"path":"modules/employee-career/js/employee-career-app.js","scriptIndex":0,"offset":2338,"line":37,"name":"url"},url);
      url.searchParams.set('scope', activeScope);
      url.searchParams.set('theme', theme());
      history.replaceState({}, '', url);
    }
    render();
  }

