function openAllOptions() {
    const overlay = document.getElementById('employeeCareerAllOptions');;window.__pqExportCapture({"path":"modules/employee-career/js/employee-career-app.js","scriptIndex":0,"offset":2574,"line":46,"name":"overlay"},overlay);
    const grid = document.getElementById('employeeCareerAllOptionsGrid');;window.__pqExportCapture({"path":"modules/employee-career/js/employee-career-app.js","scriptIndex":0,"offset":2644,"line":47,"name":"grid"},grid);
    if (!overlay || !grid) return;
    returnFocus = document.activeElement;
    grid.innerHTML = options.team.map(cardMarkup).join('');
    overlay.classList.add('active');
    overlay.setAttribute('aria-hidden', 'false');
    inertedElements = Array.from(overlay.parentElement?.children || []).filter(element => element !== overlay && !element.inert);
    inertedElements.forEach(element => { element.inert = true; });
    clearTimeout(sheetFocusTimer);
    sheetFocusTimer = setTimeout(() => {
      if (overlay.classList.contains('active')) document.getElementById('employeeCareerCloseAll')?.focus({ preventScroll: true });
    }, 250);
  }

closeAllOptions.source:
function closeAllOptions() {
    const overlay = document.getElementById('employeeCareerAllOptions');;window.__pqExportCapture({"path":"modules/employee-career/js/employee-career-app.js","scriptIndex":0,"offset":3398,"line":62,"name":"overlay"},overlay);
    if (!overlay || !overlay.classList.contains('active')) return;
    overlay.classList.remove('active');
    overlay.setAttribute('aria-hidden', 'true');
    clearTimeout(sheetFocusTimer);
    sheetFocusTimer = null;
    inertedElements.forEach(element => { element.inert = false; });
    inertedElements = [];
    if (returnFocus instanceof HTMLElement) returnFocus.focus();
    returnFocus = null;
  }

