function showToast(message) {
    const toast = document.getElementById('employeeCareerToast');;window.__pqExportCapture({"path":"modules/employee-career/js/employee-career-forms.js","scriptIndex":0,"offset":1078,"line":39,"name":"toast"},toast);
    if (!toast) return;
    toast.textContent = message;
    toast.classList.add('show');
    clearTimeout(showToast.timer);
    showToast.timer = setTimeout(() => toast.classList.remove('show'), 2200);
  }

